"""Writes the generated resources of one watch face module."""
from __future__ import annotations

from pathlib import Path

from .core import Strings
from .xml import Node, document

MANIFEST = """<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by {generator}. Watch Face Format packages are resource-only. -->
<manifest xmlns:android="http://schemas.android.com/apk/res/android">

    <uses-feature android:name="android.hardware.type.watch" />

    <application
        android:icon="@drawable/ic_launcher"
        android:label="@string/watch_face_name"
        android:hasCode="false">

        <meta-data
            android:name="com.google.android.wearable.standalone"
            android:value="true" />

        <!-- WFF v2: Flavors, weather and heart-rate sources. Requires Wear OS 5 (API 34). -->
        <property
            android:name="com.google.wear.watchface.format.version"
            android:value="2" />

        <property
            android:name="com.google.wear.watchface.format.publisher"
            android:value="devtime-wffgen-1.0" />
    </application>
</manifest>
"""

WATCH_FACE_INFO = """<?xml version="1.0" encoding="utf-8"?>
<WatchFaceInfo>
    <Preview value="@drawable/preview" />
    <Category value="CATEGORY_EMPTY" />
    <AvailableInRetail value="true" />
    <MultipleInstancesAllowed value="true" />
    <Editable value="true" />
    <FlavorsSupported value="true" />
</WatchFaceInfo>
"""


def write_module(module_dir: Path, face: Node, strings: Strings, generator: str, header: str) -> None:
    res = module_dir / "src/main/res"
    (res / "raw").mkdir(parents=True, exist_ok=True)
    (res / "xml").mkdir(parents=True, exist_ok=True)
    (res / "values").mkdir(parents=True, exist_ok=True)
    (res / "values-pt-rBR").mkdir(parents=True, exist_ok=True)

    (res / "raw/watchface.xml").write_text(document(face, header), encoding="utf-8")
    (res / "xml/watch_face_info.xml").write_text(WATCH_FACE_INFO, encoding="utf-8")
    (res / "values/strings.xml").write_text(strings.xml(0), encoding="utf-8")
    (res / "values-pt-rBR/strings.xml").write_text(strings.xml(1), encoding="utf-8")
    (module_dir / "src/main/AndroidManifest.xml").write_text(MANIFEST.format(generator=generator), encoding="utf-8")


class LayoutCheck:
    """Collects text boxes and reports any that leave the circular safe area."""

    def __init__(self, char_width_em: float = 0.6, margin: float = 10):
        self.char_width_em = char_width_em
        self.margin = margin
        self.problems: list[str] = []

    def line(self, where: str, x: float, y: float, h: float, chars: int, size: float, align: str = "START",
             box_w: float | None = None):
        from .core import circle_half_width, CENTER
        width = chars * size * self.char_width_em
        if align == "CENTER":
            cx = x + (box_w or 0) / 2
            left, right = cx - width / 2, cx + width / 2
        else:
            left, right = x, x + width
        for yy in (y + h * 0.2, y + h * 0.8):
            half = circle_half_width(yy, self.margin)
            if left < CENTER - half - 0.5 or right > CENTER + half + 0.5:
                self.problems.append(
                    f"{where}: {chars} chars @ {size}px spans x={left:.0f}..{right:.0f} at y={yy:.0f}, "
                    f"safe x={CENTER - half:.0f}..{CENTER + half:.0f}")
                return
